package com.example.nailsalon.entity; import jakarta.persistence.*; import jakarta.validation.constraints.*;
@Entity public class Material { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank private String name; @Min(0) private int quantity; @DecimalMin("0.0") private double price; public Material(){} public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public double getPrice(){return price;} public void setPrice(double v){price=v;} }
